package com.trush.game.world;

import com.trush.game.objects.Prop;

/**
 * A story stage (a floor's look and feel): its name, music, room themes (tilesets generated by
 * tools/gen_sprites.py), how layout letters map to furniture, and the door barricade style.
 * Floor 1 is the village, floor 2 the town; floors past the last stage replay it, tougher.
 */
public enum Stage {
    VILLAGE("THE VILLAGE", "village", "yard", "chapel", "square",
            new String[]{"cottage", "yard", "barn", "orchard", "square"},
            "The village is safe... for now.", false),
    TOWN("THE TOWN", "town", "street", "shop", "townhall",
            new String[]{"street", "market", "alley", "park"},
            "The town is quiet... for now.", true);

    public final String title;
    /** Track in assets/music/ (without .ogg). */
    public final String music;
    public final String startTheme;
    public final String treasureTheme;
    public final String bossTheme;
    public final String[] combatThemes;
    /** Line on the floor-clear screen. */
    public final String clearText;
    /** Locked doors: red-and-white road barriers instead of wooden planks. */
    public final boolean roadBarriers;

    Stage(String title, String music, String startTheme, String treasureTheme, String bossTheme,
          String[] combatThemes, String clearText, boolean roadBarriers) {
        this.title = title;
        this.music = music;
        this.startTheme = startTheme;
        this.treasureTheme = treasureTheme;
        this.bossTheme = bossTheme;
        this.combatThemes = combatThemes;
        this.clearText = clearText;
        this.roadBarriers = roadBarriers;
    }

    /** The stage of a story floor (1-based); floors beyond the last stage stay on it. */
    public static Stage forFloor(int floor) {
        Stage[] all = values();
        return all[Math.max(0, Math.min(floor, all.length) - 1)];
    }

    /** Furniture for a layout letter (see RoomTemplates); the town swaps hay for benches and pillars for lamps. */
    public Prop.Kind propFor(char c) {
        switch (c) {
            case 'T':
                return Prop.Kind.TABLE;
            case 'H':
                return this == TOWN ? Prop.Kind.BENCH : Prop.Kind.HAY;
            case 'B':
                return Prop.Kind.BARREL;
            case 'C':
                return Prop.Kind.CRATE;
            case 'P':
                return this == TOWN ? Prop.Kind.LAMP : Prop.Kind.PILLAR;
            default:
                return null;
        }
    }
}
